class Task {

    private static int mod = 998244353;

    public void run(int n, long k, PrintWriter out) {
        long[] fact = new long[200001];
        long[] invFact = new long[200001];
        fact[0] = invFact[0] = 1;
        for (int i = 1; i < 200001; i++) {
            fact[i] = fact[i - 1] * i % mod;
            invFact[i] = invFact[i - 1] * powMod(i, mod - 2) % mod;
        }
        if (k >= n) {
            out.println(0);
            return;
        }
        if (k == 0) {
            out.println(fact[n]);
            return;
