#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long k;
    cin >> n >> k;

    const int mod = 998244353;

    vector<long long> fact(200001, 1);
    vector<long long> invFact(200001, 1);

    auto powMod = [&](long long base, long long exp) -> long long {
        long long result = 1;
        long long baseVal = base % mod;
        while (exp > 0) {
            if (exp & 1) result = (result * baseVal) % mod;
            baseVal = (baseVal * baseVal) % mod;
            exp >>= 1;
        }
        return result;
    };

    for (int i = 1; i <= 200000; i++) {
        fact[i] = (fact[i - 1] * i) % mod;
        invFact[i] = (invFact[i - 1] * powMod(i, mod - 2)) % mod;
    }

    auto getCombination = [&](int n, int m) -> long long {
        return fact[n] * invFact[m] % mod * invFact[n - m] % mod;
    };

    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }
    if (k == 0) {
        cout << fact[n] % mod << "\n";
        return 0;
    }

    int m = n - (int)k;
    long long sum = 0;
    for (int i = 0; i <= m; i++) {
        long long c = getCombination(m, i);
        long long val = powMod(m - i, n);
        if (i % 2 == 0) {
            sum = (sum + c * val) % mod;
        } else {
            sum = (sum - c * val + mod) % mod;
        }
    }

    long long res = 2LL * fact[n] % mod * invFact[n - m] % mod * sum % mod * invFact[m] % mod;
    cout << res << "\n";

    return 0;
}
